import { useState } from 'react';

export default function {{component_name}}() {
  const [email, setEmail] = useState('');
  const [done, setDone] = useState(false);

  async function onSubmit(e: React.FormEvent) {
    e.preventDefault();
    await fetch('{{subscribe_url}}', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email }),
    });
    setDone(true);
  }

  if (done) return <p>Subscribed.</p>;
  return (
    <form onSubmit={onSubmit} className="flex gap-2">
      <input type="email" required value={email} onChange={(e) => setEmail(e.target.value)} className="border rounded px-2 py-1" />
      <button type="submit" className="px-3 py-1 bg-blue-600 text-white rounded">Subscribe</button>
    </form>
  );
}
